mersenne_exponents = {2, 3, 5, 7, 13, 17, 19, 31, 61, 89, 107, 127, 521, 607}

# Find non-clean type a classes: where x_n = p gives a ≡ 2 mod 3, a >= 2
print("Non-clean type a classes (where x_n = p gives a ≡ 2 mod 3, a >= 2):")
for p in sorted(mersenne_exponents):
    if p <= 3:
        continue  # p=2,3 handled by mod 3 analysis
