uncovered_sample = [320, 359, 509, 614, 719, 800, 842, 866, 1019, 1031, 1070, 1097, 1217, 1229, 1307, 1346, 1367, 1409, 1427, 1451]

for a in uncovered_sample:
    x1, x2, x3 = a, 2*a+1, 4*a+3
    # Check if x_n is composite
    reasons = []
    if not isprime(x1):
        reasons.append(f"x1={x1} composite")
    if not isprime(x2):
        reasons.append(f"x2={x2} composite")
    if not isprime(x3):
        reasons.append(f"x3={x3} composite")

    # If all x_n prime, check y_n
    if not reasons:
        for n, xn in [(1,x1),(2,x2),(3,x3)]:
            if xn not in mersenne_exponents:
                reasons.append(f"y{n}=2^{xn}-1 composite (xn not Mersenne exp)")

    print(f"  a={a}: {', '.join(reasons) if reasons else 'ALL PRIME?!'}")
