from sympy import isprime, primerange
from math import gcd

mersenne_exponents = {2, 3, 5, 7, 13, 17, 19, 31, 61, 89, 107, 127, 521, 607, 1279, 2203, 2281, 3217, 4253, 4423, 9689, 9941, 11213, 19937, 21701, 23209, 44497, 86243, 110503, 132049, 216091}

def is_2dm1_composite(d):
    if not isprime(d):
        return True
    return d not in mersenne_exponents

# Collect ALL classes (including Mersenne d, with edge case handling)
# For Mersenne d: class is clean EXCEPT for specific a values where x_n = d
# Those specific a values are: a = d (n=1), a = (d-1)/2 (n=2), a = (d-3)/4 (n=3)

# Strategy: use all d up to 500, and for Mersenne d, mark the edge case a values
# Then check if those edge case a values are covered by other d values

all_classes = []  # (d, r, is_clean_for_all)
edge_cases = set()  # a values that are edge cases for some Mersenne d

for d in range(3, 500, 2):  # odd d
    comp = is_2dm1_composite(d)
    inv2 = pow(2, -1, d)
    inv4 = pow(4, -1, d)

    for n, r in [(1, 0), (2, (inv2-1)%d), (3, (inv4-1)%d)]:
        if comp:
            all_classes.append((d, r, True))
        else:
            # Mersenne d: edge case when x_n = d
            if n == 1:
                a_eq = d
            elif n == 2:
                a_eq = (d-1)//2
            else:
                if (d-3) % 4 == 0:
                    a_eq = (d-3)//4
                else:
                    a_eq = None

            if a_eq is not None and a_eq >= 5 and a_eq % 3 == 2:
                # This a value is an edge case: y_n could be prime
                edge_cases.add(a_eq)
                all_classes.append((d, r, False))  # not clean for a = a_eq
            else:
                all_classes.append((d, r, True))  # clean

for d in range(4, 500, 2):  # even d
    comp = is_2dm1_composite(d)
    if comp:
        all_classes.append((d, 0, True))
    else:
        # Mersenne d, even: only n=1, edge case a = d
        if d >= 5 and d % 3 == 2:
            edge_cases.add(d)
            all_classes.append((d, 0, False))
        else:
            all_classes.append((d, 0, True))

print(f"Total classes: {len(all_classes)}")
print(f"Edge case a values: {sorted(edge_cases)}")

# Check: are all edge cases covered by clean classes?
for a_eq in sorted(edge_cases):
    covered = False
    for (d, r, clean) in all_classes:
        if clean and a_eq % d == r:
            covered = True
            break
    # Also check if a_eq is composite (then x_1 = a_eq is composite)
    if not covered and not isprime(a_eq):
        covered = True  # x_1 composite
    if not covered:
        # Check if x_2 or x_3 is composite
        x2 = 2*a_eq + 1
        x3 = 4*a_eq + 3
        if not isprime(x2) or not isprime(x3):
            covered = True
    print(f"  a={a_eq}: covered={covered}, prime={isprime(a_eq)}, x2={x2}({'P' if isprime(x2) else 'C'}), x3={x3}({'P' if isprime(x3) else 'C'})")

# Now check overall coverage with all classes (treating non-clean as clean for non-edge-case a)
uncovered = []
for a in range(5, 10000001):
    if a % 3 != 2:
        continue
    covered = False
    for (d, r, clean) in all_classes:
        if a % d == r:
            if clean or a not in edge_cases:
                covered = True
                break
    if not covered and not isprime(a):
        covered = True  # x_1 composite
    if not covered:
        uncovered.append(a)
        if len(uncovered) > 20:
            break

print(f"\nUncovered (a ≡ 2 mod 3, 5 <= a <= 10000000): {len(uncovered)}")
if uncovered:
    print(f"First 20: {uncovered[:20]}")
